  "guide/pillar-gap-ja": {
    "eyebrow": "เสาวัน",
    "title": "เสาวัน 甲子",
    "summary": "วิธีที่ Saju-Link อ่านเสาวัน 甲子 — ก้านที่กิ่งวันเก็บไว้เป็นอะไรสำหรับก้านวัน — จัดวางตรงตามกฎการคำนวณของมัน",
    "backLabel": "ฐานการคำนวณ",
    "sections": [
      {
        "title": "甲子 คือเสาวันลำดับที่ 1 ของวัฏจักรหกสิบ",
        "blocks": [
          {
            "p": "เมื่อคู่ก้าน-กิ่งของวันเกิดคือ 甲子 ก้านวันคือ 甲 (ไม้, หยาง) และกิ่งวันคือ 子 (หนู) ในวัฏจักรหกสิบ นี่คือชุดที่ 1"
          },
          {
            "p": "Saju-Link เรียกผู้ที่มีก้านวันเป็น 甲 ว่า “ไม้หยาง (甲)” และบรรทัดที่หน้าผลลัพธ์แสดงคือ: \"ต้นไม้ใหญ่ที่เติบโตตรงขึ้นไป เมื่อกำหนดทิศแล้วจะไม่หวั่นไหว และเลือกยืนหยัดมากกว่าจะโอนอ่อน\" บรรทัดนี้ไม่เกี่ยวข้องกับการอ่านด้านล่างหรือคะแนน"
          }
        ]
      },
      {
        "title": "ก้านที่กิ่งวัน 子 เก็บไว้เป็นอะไรสำหรับก้านวัน",
        "blocks": [
          {
            "p": "กิ่งวันคือตำแหน่งคู่สมรส เมื่ออ่านจากก้านวัน 甲 ก้านที่ 子 เก็บไว้มีดังนี้ ก้านหลัก (癸) คือพลังงานตัวแทนของกิ่ง"
          },
          {
            "table": {
              "caption": "ก้านซ่อนของกิ่งวัน 甲子",
              "head": [
                "ก้านซ่อน",
                "ตำแหน่ง",
                "สัดส่วน",
                "สำหรับก้านวัน 甲"
              ],
              "rows": [
                [
                  "น้ำหยาง (壬)",
                  "ส่วนเหลือ (餘氣)",
                  "{hidJaYeo}",
                  "ผู้เกื้อหนุนนอกแบบ (偏印)"
                ],
                [
                  "น้ำหยิน (癸)",
                  "หลัก (本氣)",
                  "{hidJaBon}",
                  "ผู้โอบอุ้ม (正印)"
                ]
              ]
            }
          }
        ]
      },
      {
        "title": "ตำแหน่งคู่สมรสและเสาวันนี้",
        "blocks": [
          {
            "p": "เมียงรีแบบดั้งเดิมอ่านตำแหน่งคู่สมรสเป็นทรัพย์มั่นคง (正財) สำหรับผู้ชาย และผู้วางระเบียบ (正官) สำหรับผู้หญิง เมื่อ 甲 เป็นก้านวัน ทรัพย์มั่นคงคือ 己 และผู้วางระเบียบคือ 辛"
          },
          {
            "p": "สำหรับผู้ชาย ตำแหน่งคู่สมรส (ทรัพย์มั่นคง) คือ 己 แต่ 己 ไม่ได้ถูกเก็บไว้ใน 子"
          },
          {
            "p": "สำหรับผู้หญิง ตำแหน่งคู่สมรส (ผู้วางระเบียบ) คือ 辛 แต่ 辛 ไม่ได้ถูกเก็บไว้ใน 子"
          }
        ]
      },
      {
        "title": "เสาวันข้างเคียงและอักขระที่ประกอบขึ้น",
        "blocks": [
          {
            "p": "ในวัฏจักรหกสิบ เสาวันก่อนหน้าคือ [癸亥](/guide/pillar-gye-hae) และเสาถัดไปคือ [乙丑](/guide/pillar-eul-chuk)"
          },
          {
            "p": "ประกอบขึ้นจาก [ไม้หยาง (甲)](/guide/stem-gap) และ [子 (หนู)](/guide/branch-ja)"
          }
        ]
      },
      {
        "kind": "note",
        "title": "สิ่งที่คู่มือนี้ไม่ได้บอก",
        "blocks": [
          {
            "ul": [
              "เสาวันเดียวไม่ได้ตัดสินตัวคนหรือความสัมพันธ์ ซาจูอ่านจากความสัมพันธ์ของอักขระแปดตัวในสี่เสา",
              "การอ่านตำแหน่งคู่สมรสสืบทอดกฎของเมียงรีแบบดั้งเดิม และหากไม่ระบุเพศ จะไม่อ่านตำแหน่งนี้"
            ]
          }
        ]
      }
    ]
  },

