    "summary": "วิธีที่ Saju-Link อ่านเสาวัน 癸酉 — ก้านที่กิ่งวันเก็บไว้เป็นอะไรสำหรับก้านวัน — จัดวางตรงตามกฎการคำนวณของมัน",
