    "summary": "อธิบายอย่างเข้าใจง่ายด้วยตารางสองตาราง ว่าอักษรแปดตัวของซาจูคืออะไร และก้านฟ้า กิ่งดิน กับเสาวันแต่ละอย่างหมายถึงอะไร",
