            "p": "ลองมองก้านฟ้าเป็นป้ายบอกชนิดของพลังงาน และกิ่งดินเป็นป้ายบอกเวลาและตำแหน่ง ไม่จำเป็นต้องท่องจำ เหมือนที่เราไม่ต้องท่องชื่อวันในสัปดาห์ เพียงค้นดูจากตารางด้านล่างก็พอ ส่วนเสาทั้งสี่กลายเป็นอักษรแปดตัวได้อย่างไร อธิบายไว้ใน[คู่มือแผนภูมิวันเกิด](/guide/natal-chart)"
