  "guide/ten-gods": {
    "eyebrow": "สิบเทพ",
    "title": "สิบเทพ — สิบตำแหน่งภายใน saju ของฉัน",
    "summary": "ตามเสาหมายวัน ตัวอักษรที่เหลือจะถูกแบ่งออกเป็นสิบชื่อ มันพูดถึงเหตุผลในการแยกความมั่งคั่งปกติและความมั่งคั่งข้างเคียง แม้ว่าจะเป็นองค์ประกอบความมั่งคั่งเดียวกัน.",
    "backLabel": "พื้นฐานการคำนวณ",
    "sections": [
      {
        "title": "เสาหมายวันคือบุคคลเอง",
        "blocks": [
          {
            "p": "ในบรรดาตัวอักษรแปดตัวของ saju **เสาหมายวัน** (เสาหมายสวรรค์ของวันเกิด) หมายถึงบุคคลเอง ตัวอักษรที่เหลืออีกเจ็ดตัวถูกอ่านว่าเป็นสภาพแวดล้อมที่เสาหมายวันนั้นมีอยู่."
          },
          {
            "p": "**สิบเทพ** (十神) คือการแบ่งสิบส่วนของวิธีที่เสาหมายวันรับรู้ตัวอักษรอื่นๆ พลังงานที่เลี้ยงดูฉันคือทรัพยากร พลังงานที่เหมือนกับฉันคือเพื่อน พลังงานที่ฉันให้กำเนิดคืออาหารและความมั่งคั่ง พลังงานที่กดดันฉันคือตำแหน่งทางการ และพลังงานที่ฉันกดดันคือความมั่งคั่ง — หมวดหมู่ทั้งห้านี้จะแบ่งออกเป็นหยินและหยาง ทำให้เกิดสิบ."
          }
        ]
      },
      {
        "title": "ความหมายของตัวอักษรที่เหลืออีกเจ็ดตัวต่อฉัน",
        "blocks": [
          {
            "p": "เมื่อเสาหมายวันถูกกำหนด ตัวอักษรที่เหลือในแผนภูมิเกิดจะได้รับชื่อแต่ละตัว พลังงานที่ให้กำเนิดฉัน พลังงานที่เหมือนกับฉัน พลังงานที่ฉันให้กำเนิด พลังงานที่กดดันฉัน และพลังงานที่ฉันกดดัน — สาขาทั้งห้านี้จะแบ่งออกเป็น **สิบ** ผ่านหยินและหยาง นี่คือสิบเทพ."
          },
          {
            "p": "ดังนั้น สิบเทพจึงหมายถึงไม่ใช่ความสัมพันธ์กับผู้อื่น แต่หมายถึง **ตำแหน่งภายในตัวฉันเอง** ตำแหน่งใดที่หนาหรือบางบ่งบอกถึงแนวโน้มและวิธีการใช้ชีวิตของฉัน."
          }
        ]
      },
      {
        "title": "ทำไมเราถึงอ่านสิ่งนี้ผ่านสิบเทพแทนที่จะเป็นความสัมพันธ์ของสามองค์ประกอบ",
        "blocks": [
          {
            "p": "ยังมีวิธีการมองความสัมพันธ์ของวันสเตมเพียงผ่านสามด้านของ **โหงวเฮ้ง** (supporting, same, and opposing) ซึ่งเป็นวิธีที่ง่าย แต่ **หยินและหยางหายไป** 甲 (ไม้หยาง) และ 乙 (ไม้น้ำ) กลายเป็นเหมือนกับ 甲 ซึ่งเป็นตัวแทนของ 'ความเหมือนกัน' และความสัมพันธ์ที่ตรงกันข้ามจะถูกรวมเข้าด้วยกันเป็นคะแนนเดียวโดยไม่มีทิศทางหรือหยินและหยาง."
          },
          {
            "p": "ตำแหน่งคู่สมรสต้องได้รับการประเมินตาม **สิบเทพ** ในแง่ของหยินและหยาง หากรายการที่มองผ่าน **โหงวเฮ้ง** ถูกผสมกับรายการที่มองผ่าน **สิบเทพ** ในเครื่องยนต์เดียว จะมีมาตรฐานสองอย่างสำหรับตัวละครทั้งสองตัว ดังนั้นเราจึงรวมไว้ภายใต้ **สิบเทพ**."
          }
        ]
      },
      {
        "title": "ตำแหน่งคู่สมรสคือ **ทรัพย์สมบัติที่ถูกต้อง (正財)** และ **เจ้าหน้าที่ที่ถูกต้อง (正官)**",
        "blocks": [
          {
            "p": "การทำนายโชคชะตาแบบดั้งเดิมมองตำแหน่งคู่สมรสแตกต่างกันตามเพศ สำหรับผู้ชายคือ **ทรัพย์สมบัติที่ถูกต้อง (正財)** และสำหรับผู้หญิงคือ **เจ้าหน้าที่ที่ถูกต้อง (正官)** แม้ว่าพวกเขาจะเป็นองค์ประกอบทรัพย์สินเดียวกัน แต่เฉพาะ **ทรัพย์สมบัติที่ถูกต้อง** ที่ไม่ตรงกันในหยินและหยางเท่านั้นที่ถือว่าเป็นตำแหน่งคู่สมรส ในขณะที่ **ทรัพย์สมบัติทางอ้อม** จะถูกอ่านไม่ใช่ในฐานะคู่สมรส แต่ในแง่ของกิจกรรมและทรัพย์สมบัติ."
          }
        ]
      },
      {
        "kind": "note",
        "title": "หากคุณไม่ระบุเพศ ตำแหน่งนี้จะถูกละเว้น",
        "blocks": [
          {
            "p": "นี่เป็นเพราะไม่สามารถกำหนดได้ว่าควรพิจารณา **ทรัพย์สมบัติที่ถูกต้อง** หรือ **เจ้าหน้าที่ที่ถูกต้อง** เป็นตำแหน่งคู่สมรส แทนที่จะเดาเพื่อเติมค่าที่ขาดหายไป เราจะอ่านรายการที่เหลือโดยไม่มีรายการนั้น."
          }
        ]
      }
    ]
  },
